p=s.primitives(); Q=p['top_down_quat'](0)
def snap(label):
 o=s.objects(); print(label,'step',s.n_steps,'ee',np.round(s.ee_pose()[0],4),'can',np.round(o['tomato_soup_can']['position'],4),'g',round(s.gripper_angle(),4),'bin',np.round(o['bin_a06']['position'],3),flush=True)
def mv(v,speed=.2):
 try:p['move_ee'](v,Q,speed=speed,max_steps=110)
 except Exception as e: print('ERR',e,flush=True)
for z in [.065,.025,.09,.045,.015]:
 print('TRIAL',z,flush=True);s.reset();o=s.objects()['tomato_soup_can']['position'];x,y=o[:2]
 p['open_gripper'](5);mv([x,y,.2]);mv([x,y,z],.12);snap('preclose')
 p['close_gripper'](30);snap('postclose')
 for dz in [.03,.03,.04,.05]:
  c=s.ee_pose()[0];mv([x,y,c[2]+dz],.08);snap('lift')
 print('ENDTRIAL',z,flush=True)
PY
